    <div>当前：<span class="val" id="vN">70</span> ×10⁹ 参数</div>
  </div>
  <div class="ctrl">
    <label for="sB0">每个权重的字节数 b<sub>W</sub> <span class="unit">单位：byte/参数</span></label>
