(function(){
  var DEF = {N_b:70, w_bytes:1, beta_tbps:3.35, pi_tflops:989.4, batch:1};
  var KEYS = Object.keys(DEF);
  var initial = (window.presentation && window.presentation.initialState) ? window.presentation.initialState : {};
  var state = {};
  KEYS.forEach(function(k){
    var v = initial[k];
    state[k] = (typeof v === 'number' && isFinite(v)) ? v : DEF[k];
  });

  var $ = function(id){ return document.getElementById(id); };
  var lastVisibleStep = null;

  function compute(s){
    var N = s.N_b * 1e9;
    var beta = s.beta_tbps * 1e12;
    var pi = s.pi_tflops * 1e12;
    var RW = N * s.w_bytes;
    var F = 2 * s.batch * N;
    var tRead = RW / beta * 1000;
    var tComp = F / pi * 1000;
    var step = Math.max(tRead, tComp);
    return {
      N:N, beta:beta, pi:pi, RW:RW, F:F, tRead:tRead, tComp:tComp, step:step,
      perOut: step / s.batch,
      tput: s.batch / step * 1000,
      Bstar: s.w_bytes * pi / (2 * beta),
      I: F / RW,
      balance: pi / beta,
      readWins: tRead >= tComp
    };
  }

  function ms(v){ return v >= 1 ? v.toFixed(2) : v.toFixed(4); }

  function syncInputs(){
    $('sN').value = state.N_b;
    $('sBeta').value = state.beta_tbps;
    $('sPi').value = state.pi_tflops;
    $('sBatch').value = state.batch;
    var radios = document.querySelectorAll('input[name=bw]');
    for (var i = 0; i < radios.length; i++){
      radios[i].checked = (parseFloat(radios[i].value) === state.w_bytes);
    }
  }

  function render(){
    var r = compute(state);
    $('vN').textContent = state.N_b;
    $('vBeta').textContent = Number(state.beta_tbps).toFixed(2);
    $('vPi').textContent = Number(state.pi_tflops).toFixed(1);
    $('vBatch').textContent = state.batch;

    var maxT = Math.max(r.tRead, r.tComp);
    $('fillRead').style.width = (r.tRead / maxT * 100).toFixed(2) + '%';
    $('fillComp').style.width = (r.tComp / maxT * 100).toFixed(2) + '%';
    $('vReadBar').textContent = ms(r.tRead) + ' ms';
    $('vCompBar').textContent = ms(r.tComp) + ' ms';

    var v = $('verdict');
    if (r.readWins){
      var ratio = r.tComp > 0 ? (r.tRead / r.tComp) : Infinity;
      v.className = 'verdict win-read';
      v.textContent = '这一步由读取决定：读取下界 ' + ms(r.tRead) + ' ms 是计算下界 ' +
        (r.tComp >= 1 ? r.tComp.toFixed(2) : r.tComp.toFixed(4)) + ' ms 的 ' +
        (ratio >= 100 ? ratio.toFixed(0) : ratio.toFixed(1)) + ' 倍。要让这一步更快，先让显存少搬数据或搬得更快。';
      lastVisibleStep = '读取决定';
    } else {
      var ratio2 = r.tRead > 0 ? (r.tComp / r.tRead) : Infinity;
      v.className = 'verdict win-comp';
      v.textContent = '这一步由计算决定：计算下界 ' + ms(r.tComp) + ' ms 比读取下界 ' + ms(r.tRead) +
        ' ms 更长（' + (ratio2 >= 100 ? ratio2.toFixed(0) : ratio2.toFixed(1)) + ' 倍）。要让这一步更快，先提高算力，或者别让计算量随批量一起涨。';
      lastVisibleStep = '计算决定';
    }

    $('outRW').textContent = (r.RW / 1e9).toFixed(1) + ' GB';
    $('outRead').textContent = ms(r.tRead) + ' ms';
    $('outF').textContent = (r.F / 1e9).toFixed(0) + ' GFLOPs';
    $('outComp').textContent = ms(r.tComp) + ' ms';
    $('outStep').textContent = ms(r.step) + ' ms';
    $('outPer').textContent = ms(r.perOut) + ' ms / token';
    $('outTput').textContent = (r.tput >= 100 ? r.tput.toFixed(0) : r.tput.toFixed(1)) + ' token/s';
    $('outBstar').textContent = r.Bstar.toFixed(1) + ' 个请求';
    $('outI').textContent = r.I.toFixed(2) + ' FLOP/byte';
    $('outInote').textContent = '机器平衡点 Π / β = ' + r.balance.toFixed(1) + ' FLOP/byte；I 小于它，说明读取所需时间更长。';

    var b = state.batch;
    var bNote;
    if (b <= 1 && r.Bstar < 1) bNote = '当前参数下计算已经更慢（B* < 1），批内复用不能把瓶颈重新变回读取。';
    else if (b < r.Bstar) bNote = '当前 B = ' + b + '，仍小于转折点 ' + r.Bstar.toFixed(1) + '：权重读取依旧是较长的一项，增加 B 主要是在摊薄这 20.90 ms 那一类的读取时间。';
    else if (b === Math.round(r.Bstar)) bNote = '当前 B = ' + b + '，正好在转折点上：读取与计算两项下界相等。';
    else bNote = '当前 B = ' + b + '，已经超过转折点 ' + r.Bstar.toFixed(1) + '：计算成为较长的一项，再加大 B，整批时间会随 B 一起增长。';
    $('bNote').textContent = bNote;

    var isPreset = KEYS.every(function(k){ return state[k] === DEF[k]; });
    $('stateNote').textContent = isPreset ? '当前参数＝书中算例，结果卡应复现 20.90 ms / 0.1415 ms / 47.9 token•s⁻¹。'
      : '当前参数已改动，下面是本页按同一公式现算的结果（不是书中的实测）。';
    $('presetEcho').textContent = 'N=' + state.N_b + '、b_W=' + state.w_bytes + '、β=' + Number(state.beta_tbps).toFixed(2) +
      '、Π=' + Number(state.pi_tflops).toFixed(1) + '、B=' + state.batch;
  }

  function setParam(k, v){
    var n = parseFloat(v);
    if (!isFinite(n)) return;
    state[k] = n;
    render();
  }

  $('sN').addEventListener('input', function(){ setParam('N_b', this.value); });
  $('sBeta').addEventListener('input', function(){ setParam('beta_tbps', this.value); });
  $('sPi').addEventListener('input', function(){ setParam('pi_tflops', this.value); });
  $('sBatch').addEventListener('input', function(){ setParam('batch', this.value); });
  document.querySelectorAll('input[name=bw]').forEach(function(el){
    el.addEventListener('change', function(){ setParam('w_bytes', this.value); });
  });
  $('resetBtn').addEventListener('click', function(){
    KEYS.forEach(function(k){ state[k] = DEF[k]; });
    syncInputs(); render();
    if (window.presentation && window.presentation.commitState) window.presentation.commitState();
  });
  $('presetBtn').addEventListener('click', function(){
    KEYS.forEach(function(k){ state[k] = DEF[k]; });
    syncInputs(); render();
    if (window.presentation && window.presentation.commitState) window.presentation.commitState();
  });

  if (window.presentation && window.presentation.registerStateReader){
    window.presentation.registerStateReader(function(){
      return {
        values: {N_b:state.N_b, w_bytes:state.w_bytes, beta_tbps:state.beta_tbps, pi_tflops:state.pi_tflops, batch:state.batch},
        visible_step: lastVisibleStep
      };
    });
  }
  if (window.presentation && window.presentation.registerStateRestorer){
    window.presentation.registerStateRestorer(function(saved){
      if (saved && saved.values){
        KEYS.forEach(function(k){
          var v = saved.values[k];
          if (typeof v === 'number' && isFinite(v)) state[k] = v;
        });
      }
      syncInputs(); render();
    });
  }

  syncInputs();
  render();
})();
</script>
